CREATE TABLE IF NOT EXISTS users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'customer',active INTEGER NOT NULL DEFAULT 1,session_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reset_tokens(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,parent_id INTEGER REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS products(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category_id INTEGER NOT NULL REFERENCES categories(id),name TEXT NOT NULL,description TEXT NOT NULL,brand TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),selling_unit TEXT NOT NULL,pack_quantity INTEGER NOT NULL CHECK(pack_quantity>0),attributes TEXT NOT NULL DEFAULT '{}',image TEXT NOT NULL,published INTEGER NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0,CHECK(stock>=reserved AND reserved>=0));
CREATE TABLE IF NOT EXISTS cart_items(owner TEXT NOT NULL,product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(owner,product_id));
CREATE TABLE IF NOT EXISTS promotions(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT UNIQUE NOT NULL,percent INTEGER CHECK(percent BETWEEN 1 AND 50),minimum INTEGER CHECK(minimum>=0),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),idem_key TEXT NOT NULL,request_hash TEXT NOT NULL,recipient TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,subtotal INTEGER NOT NULL,discount INTEGER NOT NULL,shipping INTEGER NOT NULL,total INTEGER NOT NULL,promo TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,UNIQUE(user_id,idem_key));
CREATE TABLE IF NOT EXISTS order_items(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),product_id INTEGER NOT NULL REFERENCES products(id),name TEXT NOT NULL,selling_unit TEXT NOT NULL,pack_quantity INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),price INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments(order_id INTEGER PRIMARY KEY REFERENCES orders(id),method TEXT NOT NULL,status TEXT NOT NULL,reference TEXT NOT NULL,amount INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payment_events(event_id TEXT PRIMARY KEY,order_id INTEGER REFERENCES orders(id),result TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_movements(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id INTEGER REFERENCES products(id),order_id INTEGER REFERENCES orders(id),quantity INTEGER NOT NULL,kind TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_history(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INTEGER REFERENCES orders(id),status TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER REFERENCES users(id),message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER REFERENCES users(id),product_id INTEGER REFERENCES products(id),rating INTEGER CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS shipments(order_id INTEGER PRIMARY KEY REFERENCES orders(id),provider TEXT NOT NULL,tracking_code TEXT UNIQUE NOT NULL,status TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tracking_events(event_id TEXT PRIMARY KEY,order_id INTEGER REFERENCES orders(id),status TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_cases(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER REFERENCES users(id),order_id INTEGER REFERENCES orders(id),product_id INTEGER REFERENCES products(id),subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',reply TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS replenishments(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,supplier TEXT NOT NULL,product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL DEFAULT 'requested',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,record TEXT NOT NULL,created_at TEXT NOT NULL);
